// Resolución simplificada de intents implícitos: acción, categoría y esquema de datos.
// Los filtros son los dos de MainActivity en el manifest que generó expo prebuild para Senda.
const filtros = [
  { nombre: "filtro 1 (ícono)", acciones: ["android.intent.action.MAIN"],
    categorias: ["android.intent.category.LAUNCHER"], esquemas: [] },
  { nombre: "filtro 2 (enlace)", acciones: ["android.intent.action.VIEW"],
    categorias: ["android.intent.category.DEFAULT", "android.intent.category.BROWSABLE"], esquemas: ["senda"] },
];

function pasa(intent, f) {
  // prueba de acción: la del intent tiene que estar en el filtro
  if (!f.acciones.includes(intent.accion)) return "falla la acción";
  // prueba de categoría: cada categoría del intent tiene que estar en el filtro
  for (const c of intent.categorias) if (!f.categorias.includes(c)) return "falla la categoría " + c.split(".").pop();
  // prueba de datos: si el filtro pide esquema, el del intent tiene que coincidir
  if (f.esquemas.length > 0 && !f.esquemas.includes(intent.esquema)) return "falla el esquema";
  if (f.esquemas.length === 0 && intent.esquema) return "falla: el filtro no admite datos";
  return "PASA";
}

const DEF = "android.intent.category.DEFAULT";
const intents = [
  { t: "tocar el ícono (MAIN + LAUNCHER)", accion: "android.intent.action.MAIN", categorias: ["android.intent.category.LAUNCHER"], esquema: null },
  { t: "abrir senda://unirme/ABC12345", accion: "android.intent.action.VIEW", categorias: [DEF, "android.intent.category.BROWSABLE"], esquema: "senda" },
  { t: "abrir https://meet.google.com/new", accion: "android.intent.action.VIEW", categorias: [DEF], esquema: "https" },
  { t: "compartir texto (SEND)", accion: "android.intent.action.SEND", categorias: [DEF], esquema: null },
];

for (const i of intents) {
  const r = filtros.map((f) => f.nombre + ": " + pasa(i, f));
  console.log(i.t + "\n  " + r.join("\n  "));
}
